1	import type {
2		ConversationJudgeResult,
3		ConversationNextResult,
4		ConversationSessionStartResult,
5		ConversationVerdict,
6	} from "../../domain/conversation/types";
7	import type { ConversationPracticePort } from "../../domain/ports/ConversationPracticePort";
8	
9	/**
10	 * Where the local conversation backend listens (`docs/conversation-backend-api.md`).
11	 * A module constant, not user-configurable: the backend is a local-only,
12	 * single-user process, and the deployed GitHub Pages build can't reach it at
13	 * all — which is exactly the `"unavailable"` path below.
14	 */
15	export const CONVERSATION_BACKEND_BASE_URL = "http://localhost:8000";
16	
17	/**
18	 * Generous on purpose: a cold backend loads Whisper, a 7B judge model and
19	 * TTS before it answers, and a judged reply is seconds of real GPU work. The
20	 * deadline exists so a request that never settles can't wedge the page
21	 * forever, not to police latency.
22	 */
23	export const CONVERSATION_REQUEST_TIMEOUT_MS = 60_000;
24	
25	function isString(value: unknown): value is string {
26		return typeof value === "string";
27	}
28	
29	function isVerdict(value: unknown): value is ConversationVerdict {
30		return value === "pass" || value === "fail" || value === "unscored";
31	}
32	
33	function asRecord(value: unknown): Record<string, unknown> | null {
34		return typeof value === "object" && value !== null
35			? (value as Record<string, unknown>)
36			: null;
37	}
38	
39	/**
40	 * One request, with every failure flattened to `null`.
41	 *
42	 * `null` means "the backend did not answer with a usable body" and covers
43	 * all three failure shapes the port collapses together: `fetch` rejecting
44	 * (backend not running), a non-2xx status — checked *before* the body is
45	 * parsed, since a `500`/`422`/`404` resolves perfectly happily from
46	 * `fetch`'s point of view — and a request that never settles.
47	 *
48	 * The deadline is raced rather than left to the `AbortController` alone: the
49	 * controller is what actually cancels the in-flight request, but racing is
50	 * what guarantees this function returns even if nothing ever honours the
51	 * signal.
52	 */
53	async function fetchJson(
54		path: string,
55		init: RequestInit = {},
56	): Promise<unknown> {
57		const controller = new AbortController();
58		let timer: ReturnType<typeof setTimeout> | undefined;
59		const deadline = new Promise<null>((resolve) => {
60			timer = setTimeout(() => {
61				controller.abort();
62				resolve(null);
63			}, CONVERSATION_REQUEST_TIMEOUT_MS);
64		});
65		const attempt = (async (): Promise<unknown> => {
66			const response = await fetch(`${CONVERSATION_BACKEND_BASE_URL}${path}`, {
67				...init,
68				signal: controller.signal,
69			});
70			return response.ok ? await response.json() : null;
71		})().catch(() => null);
72	
73		try {
74			return await Promise.race([attempt, deadline]);
75		} finally {
76			clearTimeout(timer);
77		}
78	}
79	
80	/** base64 → a `blob:` URL an `<audio>`/`new Audio(url)` can play. */
81	function toBlobUrl(base64: string, mimeType: string): string {
82		const binary = atob(base64);
83		const bytes = new Uint8Array(binary.length);
84		for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
85		return URL.createObjectURL(new Blob([bytes], { type: mimeType }));
86	}
87	
88	/** A recorded `Blob` → base64, chunked so a long take can't blow the stack. */
89	async function toBase64(blob: Blob): Promise<string> {
90		const bytes = new Uint8Array(await blob.arrayBuffer());
91		const CHUNK = 0x8000;
92		let binary = "";
93		for (let offset = 0; offset < bytes.length; offset += CHUNK) {
94			binary += String.fromCharCode(...bytes.subarray(offset, offset + CHUNK));
95		}
96		return btoa(binary);
97	}
98	
99	/** Reads `{question_text, question_audio_base64, question_audio_mime_type}` off `body`, or `null` if any is missing/not a string. */
100	function questionFields(
101		body: Record<string, unknown>,
102	): { questionText: string; questionAudioUrl: string } | null {
103		const { question_text, question_audio_base64, question_audio_mime_type } =
104			body;
105		if (
106			!isString(question_text) ||
107			!isString(question_audio_base64) ||
108			!isString(question_audio_mime_type)
109		) {
110			return null;
111		}
112		try {
113			return {
114				questionText: question_text,
115				questionAudioUrl: toBlobUrl(
116					question_audio_base64,
117					question_audio_mime_type,
118				),
119			};
120		} catch {
121			// Undecodable base64 is a backend that isn't answering usefully.
122			return null;
123		}
124	}
125	
126	/**
127	 * `ConversationPracticePort` over the local backend's HTTP contract
128	 * (`docs/conversation-backend-api.md`).
129	 *
130	 * Audio crosses the wire as base64 paired with the MIME type it was actually
131	 * encoded as, in both directions — never an assumed `audio/wav`. Outbound
132	 * that means the recorded `Blob`'s own `.type`, because `useMicRecorder` has
133	 * no fixed output format (Chromium gives `audio/webm;codecs=opus`); inbound
134	 * it means the response's declared `question_audio_mime_type`.
135	 */
136	export class HttpConversationPracticeClient
137		implements ConversationPracticePort
138	{
139		async startSession(
140			knownWords: string[],
141		): Promise<ConversationSessionStartResult> {
142			const body = asRecord(
143				await fetchJson("/conversation/session/start", {
144					method: "POST",
145					headers: { "Content-Type": "application/json" },
146					body: JSON.stringify({ known_words: knownWords }),
147				}),
148			);
149			if (!body || !isString(body.session_id)) return { status: "unavailable" };
150	
151			const question = questionFields(body);
152			if (!question) return { status: "unavailable" };
153	
154			return { status: "ok", sessionId: body.session_id, ...question };
155		}
156	
157		async next(sessionId: string): Promise<ConversationNextResult> {
158			const body = asRecord(
159				await fetchJson(
160					`/conversation/session/${encodeURIComponent(sessionId)}/next`,
161					{ method: "POST" },
162				),
163			);
164			if (!body) return { status: "unavailable" };
165			if (body.exhausted === true) return { status: "exhausted" };
166	
167			const question = questionFields(body);
168			if (!question) return { status: "unavailable" };
169	
170			return { status: "ok", ...question };
171		}
172	
173		async judgeReply(
174			sessionId: string,
175			questionText: string,
176			replyAudio: Blob,
177		): Promise<ConversationJudgeResult> {
178			let replyAudioBase64: string;
179			try {
180				replyAudioBase64 = await toBase64(replyAudio);
181			} catch {
182				return { status: "unavailable" };
183			}
184	
185			const body = asRecord(
186				await fetchJson(
187					`/conversation/session/${encodeURIComponent(sessionId)}/judge`,
188					{
189						method: "POST",
190						headers: { "Content-Type": "application/json" },
191						body: JSON.stringify({
192							question_text: questionText,
193							reply_audio_base64: replyAudioBase64,
194							reply_audio_mime_type: replyAudio.type,
195						}),
196					},
197				),
198			);
199			if (!body) return { status: "unavailable" };
200	
201			const { transcript, verdict, feedback_en } = body;
202			if (
203				!isString(transcript) ||
204				!isVerdict(verdict) ||
205				!isString(feedback_en)
206			) {
207				return { status: "unavailable" };
208			}
209	
210			return { status: "ok", transcript, verdict, feedbackEn: feedback_en };
211		}
212	}
213

