		const [, init] = fetchSpy.mock.calls[0] as [string, RequestInit];
		expect(JSON.parse(init.body as string)).toEqual({ known_words: [] });
	});

	it("accepts a realistic 600-word known-word snapshot without truncating it", async () => {
