328	describe("ConversationPracticePage — question-audio blob URLs (AC4)", () => {
329		it("revokes the previous question's blob URL when the page advances to the next one", async () => {
330			const port = portWithSession();
331			port.judgement = {
332				status: "ok",
333				transcript: "a",
334				verdict: "pass",
335				feedbackEn: "",
336			};
337			port.nextResult = {
338				status: "ok",
339				questionText: "q2",
340				questionAudioUrl: "blob:q2",
341			};
342			renderPage(port);
343	
344			await screen.findByText("สบายดีไหม");
345			expect(revokedObjectUrls()).not.toContain("blob:question-audio");
346	
347			await recordAndStop();
348			await screen.findByText("q2");
349	
350			expect(revokedObjectUrls()).toContain("blob:question-audio");
351		});
352	
353		it("revokes the active question's blob URL on unmount", async () => {
354			const { unmount } = renderPage(portWithSession());
355			await screen.findByText("สบายดีไหม");
356	
357			unmount();
358	
359			expect(revokedObjectUrls()).toContain("blob:question-audio");
360		});
361	});
362	
363	describe("ConversationPracticePage — microphone failures", () => {
364		it("shows a microphone-access message distinct from the backend-unavailable one when permission is denied", async () => {
365			setMicPermission("denied");
366			renderPage(portWithSession());
367	
368			const recordButton = await screen.findByRole("button", {
369				name: "Record your reply",
370			});
371			await act(async () => {
372				fireEvent.click(recordButton);
373			});
374	
375			const alert = await screen.findByRole("alert");
